import numpy as np

def matrix_multiply(A, B):
    return np.dot(A, B)

import numpy as np

def compute_stats(data):
    return float(np.mean(data)), float(np.var(data)), float(np.std(data))

import numpy as np

def normalize(data):
    min_val = np.min(data)
    max_val = np.max(data)
    return (data - min_val) / (max_val - min_val)

import numpy as np

def euclidean_distance(a, b):
    return np.sqrt(np.sum((a - b) ** 2))

import numpy as np

def mse(y_true, y_pred):
    return np.mean((y_true - y_pred) ** 2)

import numpy as np

def sigmoid(z):
    return 1 / (1 + np.exp(-z))

import numpy as np

def gini(labels):
    _, counts = np.unique(labels, return_counts=True)
    probs = counts / len(labels)
    return 1.0 - np.sum(probs ** 2)
